package com.acme.voting.ballots;

/**
 * Prevents double voting by checking the voter's participation record.
 */
public class SingleBallotGuard {

    private final ParticipationRepository participation;

    public SingleBallotGuard(ParticipationRepository participation) {
        this.participation = participation;
    }

    public void assertHasNotVoted(String voterId, String electionId) {
        if (participation.hasVoted(voterId, electionId)) {
            throw new DuplicateBallotException(voterId, electionId);
        }
    }
}

class DuplicateBallotException extends RuntimeException {
    public DuplicateBallotException(String voterId, String electionId) {
        super("Voter " + voterId + " has already voted in " + electionId);
    }
}

