package com.acme.voting.tally;

import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Tallies first-preference votes and identifies the leading candidate.
 */
public class FirstPastThePostTally {

    private final BallotRepository ballots;

    public FirstPastThePostTally(BallotRepository ballots) {
        this.ballots = ballots;
    }

    public TallyResult tally(String electionId) {
        List<CastBallot> cast = ballots.findAllForElection(electionId);
        Map<String, Long> counts = new HashMap<>();
        for (CastBallot b : cast) {
            String first = b.getPreferenceOrder().get(0);
            counts.merge(first, 1L, Long::sum);
        }
        String winner = counts.entrySet().stream()
            .max(Comparator.comparingLong(Map.Entry::getValue))
            .map(Map.Entry::getKey)
            .orElse(null);
        return new TallyResult(counts, winner, cast.size());
    }
}

