package com.acme.voting.web;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Cast-ballot endpoint: eligibility, single-ballot rule, persistence, receipt.
 */
@RestController
public class CastBallotController {

    private final SingleBallotGuard singleBallot;
    private final BallotRepository ballots;
    private final ParticipationRepository participation;
    private final ReceiptSigner signer;

    public CastBallotController(SingleBallotGuard singleBallot, BallotRepository ballots,
                                ParticipationRepository participation, ReceiptSigner signer) {
        this.singleBallot = singleBallot;
        this.ballots = ballots;
        this.participation = participation;
        this.signer = signer;
    }

    @PostMapping("/ballots")
    public BallotReceipt cast(@RequestBody CastBallotRequest req) {
        singleBallot.assertHasNotVoted(req.getVoterId(), req.getElectionId());
        CastBallot b = ballots.save(CastBallot.of(req));
        participation.markVoted(req.getVoterId(), req.getElectionId());
        String receipt = signer.sign(b.getId(), req.getElectionId());
        return new BallotReceipt(b.getId(), receipt);
    }
}

