package com.acme.voting.auth;

import java.time.Duration;
import java.time.Instant;

/**
 * Verifies a one-time code sent to the voter's registered channel.
 */
public class OtpVerificationService {

    private static final Duration VALIDITY = Duration.ofMinutes(5);
    private static final int MAX_ATTEMPTS = 3;

    private final OtpRepository otps;

    public OtpVerificationService(OtpRepository otps) {
        this.otps = otps;
    }

    public boolean verify(String voterId, String code, Instant now) {
        Otp otp = otps.latestFor(voterId).orElseThrow(() -> new IllegalStateException("No code issued"));
        if (now.isAfter(otp.getIssuedAt().plus(VALIDITY))) {
            throw new ExpiredCodeException(voterId);
        }
        if (otp.getAttempts() >= MAX_ATTEMPTS) {
            throw new TooManyAttemptsException(voterId);
        }
        if (!otp.getCode().equals(code)) {
            otps.incrementAttempts(otp.getId());
            return false;
        }
        otps.markConsumed(otp.getId());
        return true;
    }
}

