package com.acme.voting.admin;

import java.time.Instant;

/**
 * Opens and closes polling for an election.
 */
public class PollingWindowService {

    private final ElectionRepository elections;

    public PollingWindowService(ElectionRepository elections) {
        this.elections = elections;
    }

    public void open(String electionId, Instant openAt) {
        Election e = elections.require(electionId);
        if (e.getStatus() != ElectionStatus.SCHEDULED) {
            throw new IllegalStateException("Election is not in SCHEDULED state");
        }
        e.setStatus(ElectionStatus.OPEN);
        e.setOpenAt(openAt);
        elections.save(e);
    }

    public void close(String electionId, Instant closeAt) {
        Election e = elections.require(electionId);
        if (e.getStatus() != ElectionStatus.OPEN) {
            throw new IllegalStateException("Election is not open");
        }
        e.setStatus(ElectionStatus.CLOSED);
        e.setCloseAt(closeAt);
        elections.save(e);
    }
}

