package com.acme.voting.privacy;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Stores ballots without voter identity, and participation separately.
 */
public class AnonymousBallotRecorder {

    private final EntityManager em;

    public AnonymousBallotRecorder(EntityManager em) {
        this.em = em;
    }

    public void record(String electionId, java.util.List<String> preferences) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            AnonymousBallot b = new AnonymousBallot();
            b.setElectionId(electionId);
            b.setPreferenceOrder(preferences);
            b.setCastAt(Instant.now());
            em.persist(b);
            tx.commit();
        } catch (RuntimeException e) {
            tx.rollback();
            throw e;
        }
    }
}

