package com.acme.voting.tally;

import java.time.Instant;

/**
 * Filters ballots to those eligible and within the window before tallying.
 */
public class ValidBallotFilter {

    private final ElectoralRoll roll;
    private final ElectionRepository elections;

    public ValidBallotFilter(ElectoralRoll roll, ElectionRepository elections) {
        this.roll = roll;
        this.elections = elections;
    }

    public boolean isValid(CastBallot b) {
        Election e = elections.require(b.getElectionId());
        if (b.getCastAt().isBefore(e.getOpenAt()) || b.getCastAt().isAfter(e.getCloseAt())) {
            return false;
        }
        if (!roll.isEligible(b.getVoterId(), b.getElectionId())) {
            return false;
        }
        if (b.getPreferenceOrder() == null || b.getPreferenceOrder().isEmpty()) {
            return false;
        }
        return true;
    }
}

