/* precinct_summary.c - write precinct result summary as CSV */
#include <stdio.h>
#include "voting_db.h"

int write_precinct_summary(const char *election_id, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "precinct,candidate,valid_ballots,votes\n");

    db_cursor_t *cur = NULL;
    if (db_open_precinct_tally_cursor(&cur, election_id) != DB_OK) { fclose(out); return -2; }

    tally_row_t row;
    int rows = 0;
    while (db_tally_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%s,%d,%d\n",
                row.precinct_code, row.candidate_id, row.valid_ballots, row.vote_count);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

